	async function getSvgDimensionsFromText(blob) {
	  const text = await blob.text();
	  
	  const widthMatch = text.match(/width=["'](\d+(?:\.\d+)?)(?:px)?["']/i);
	  const heightMatch = text.match(/height=["'](\d+(?:\.\d+)?)(?:px)?["']/i);
	  
	  const viewBoxMatch = text.match(/viewBox=["'][\d.]+\s+[\d.]+\s+([\d.]+)\s+([\d.]+)["']/i);
	  
	  const width = widthMatch ? parseFloat(widthMatch[1]) : (viewBoxMatch ? parseFloat(viewBoxMatch[1]) : 256);
	  const height = heightMatch ? parseFloat(heightMatch[1]) : (viewBoxMatch ? parseFloat(viewBoxMatch[2]) : 256);
	  
	  return { width, height };
	}
	
	async function loadSvgWithDimensions(blob, options = {}) {
	  const text = await blob.text();
	  
	  return new Promise((resolve, reject) => {
		const svgBase64 = btoa(unescape(encodeURIComponent(text)));
		const dataUrl = `data:image/svg+xml;base64,${svgBase64}`;
		
		const img = new Image();
		
		img.onload = () => {
		  const naturalWidth = img.naturalWidth || options.resizeWidth || 256;
		  const naturalHeight = img.naturalHeight || options.resizeHeight || 256;
		  
		  createImageBitmap(img, {
			resizeWidth: options.resizeWidth || naturalWidth,
			resizeHeight: options.resizeHeight || naturalHeight,
			resizeQuality: options.resizeQuality || 'high',
			premultiplyAlpha: options.premultiplyAlpha || 'none',
			imageOrientation: 'none'
		  })
		  .then(resolve)
		  .catch(reject);
		};
		
		img.onerror = (e) => {
		  reject(new Error(`Failed to load SVG from data URL: ${e}`));
		};
		
		img.src = dataUrl;
	  });
	}
	
	async function loadBitmap(url, options = {}) {
	  const res = await fetch(url);
	  if (!res.ok) throw new Error(`Failed to load ${url}: ${res.status}`);
	  
	  const blob = await res.blob();
	  const isSvg = blob.type === 'image/svg+xml' || url.toLowerCase().endsWith('.svg');
	  
	  if (!isSvg) {
		return createImageBitmap(blob, options);
	  }
	  
	  try {
		const { width, height } = await getSvgDimensionsFromText(blob);
		
		return await createImageBitmap(blob, {
		  resizeWidth: options.resizeWidth || width,
		  resizeHeight: options.resizeHeight || height,
		  resizeQuality: options.resizeQuality || 'high',
		  premultiplyAlpha: options.premultiplyAlpha || 'none'
		});
	  } catch (err) {
		return await loadSvgWithDimensions(blob, options);
	  }
	}
	
	async function loadBitmapsConcurrently(urls, config, limit = 4) {
	  const results = {};
	  const executing = new Set();

	  for (const [key, url] of Object.entries(urls)) {
		const task = (async () => {
		  results[key] = await loadBitmap(url, config);
		  executing.delete(task);
		})();
		
		executing.add(task);
		if (executing.size >= limit) {
		  await Promise.race(executing);
		}
	  }
	  await Promise.all(executing);
	  return results;
	}

